715	MerkleProofParseResult merkle_proof_from_json(std::string_view text) {
716	    MerkleProofParseResult result;
717	
718	    // 全程写入本地 proof：只有文本完整通过后才移入返回值，任何失败都不
719	    // 留下可用的部分证明（返回对象保持默认构造）。
720	    MerkleProof proof;
721	    JsonParser p;
722	    p.text = text;
723	
724	    enum FieldBit : unsigned {
725	        kVersion = 1u << 0,
726	        kRoot = 1u << 1,
727	        kLeafCount = 1u << 2,
728	        kLeafIndex = 1u << 3,
729	        kLeaf = 1u << 4,
730	        kSiblings = 1u << 5,
731	    };
732	    constexpr unsigned kAllFields = kVersion | kRoot | kLeafCount |
733	                                    kLeafIndex | kLeaf | kSiblings;
734	    unsigned seen = 0;
735	
736	    p.ws();
737	    if (p.eof()) {
738	        result.error =
739	            "proof text rejected: input is empty or whitespace only "
740	            "(expected a version 1 proof JSON object)";
741	        return result;
742	    }
743	    if (p.peek() != '{') {
744	        result.error =
745	            "proof text rejected: top-level value must be a single JSON object";
746	        return result;
747	    }
748	    ++p.pos;
749	    p.ws();
750	
751	    // 空对象（"{}"）不进入字段循环，直接落到后面的必填字段检查。
752	    if (!p.eof() && p.peek() == '}') {
753	        ++p.pos;
754	    } else {
755	        while (p.error.empty()) {
756	        p.ws();
757	        if (p.eof() || p.peek() != '"') {
758	            p.fail("expected a string field name in proof object");
759	            break;
760	        }
761	        std::string key;
762	        if (!p.read_string(key)) {
763	            break;
764	        }
765	        p.ws();
766	        if (p.eof() || p.peek() != ':') {
767	            p.fail("expected ':' after proof object field \"" + key + "\"");
768	            break;
769	        }
770	        ++p.pos;
771	
772	        unsigned bit = 0;
773	        if (key == "version") {
774	            bit = kVersion;
775	        } else if (key == "root") {
776	            bit = kRoot;
777	        } else if (key == "leaf_count") {
778	            bit = kLeafCount;
779	        } else if (key == "leaf_index") {
780	            bit = kLeafIndex;
781	        } else if (key == "leaf") {
782	            bit = kLeaf;
783	        } else if (key == "siblings") {
784	            bit = kSiblings;
785	        } else {
786	            p.fail("undefined field \"" + key + "\" in proof object (version 1 "
787	                   "defines only version, root, leaf_count, leaf_index, leaf "
788	                   "and siblings)");
789	            break;
790	        }
791	        if (seen & bit) {
792	            p.fail("duplicate field \"" + key + "\" in proof object");
793	            break;
794	        }
795	
796	        if (bit == kVersion) {
797	            std::uint64_t version = 0;
798	            if (!p.read_uint64(version, "version")) {
799	                break;
800	            }
801	            if (version != 1) {
802	                p.fail("unsupported proof version " +
803	                       std::to_string(version) + " (only version 1 is "
804	                       "supported)");
805	                break;
806	            }
807	        } else if (bit == kRoot) {
808	            if (!read_digest_value(p, proof.root, "root")) {
809	                break;
810	            }
811	        } else if (bit == kLeafCount) {
812	            if (!p.read_uint64(proof.leaf_count, "leaf_count")) {
813	                break;
814	            }
815	        } else if (bit == kLeafIndex) {
816	            if (!p.read_uint64(proof.leaf_index, "leaf_index")) {
817	                break;
818	            }
819	        } else if (bit == kLeaf) {
820	            if (!read_digest_value(p, proof.leaf, "leaf")) {
821	                break;
822	            }
823	        } else {  // kSiblings
824	            p.ws();
825	            if (p.eof() || p.peek() != '[') {
826	                p.fail("field \"siblings\" must be a JSON array");
827	                break;
828	            }
829	            if (!parse_siblings_array(p, proof.siblings)) {
830	                break;
831	            }
832	        }
833	        seen |= bit;
834	
835	        p.ws();
836	        if (p.eof()) {
837	            p.fail("unterminated proof object");
838	            break;
839	        }
840	        if (p.peek() == '}') {
841	            ++p.pos;
842	            break;
843	        }
844	        if (p.peek() != ',') {
845	            p.fail("expected ',' or '}' in proof object");
846	            break;
847	        }
848	        ++p.pos;
849	        // 逗号之后要求另一个字段名；循环回到顶部做该检查。
850	        }
851	    }
852	
853	    if (p.error.empty()) {
854	        // 对象之后除 JSON 空白外不得再有任何内容：不能只取前半段当作成功。
855	        p.ws();
856	        if (!p.eof()) {
857	            p.fail("unexpected trailing content after the proof JSON object");
858	        }
859	    }
860	    if (p.error.empty() && seen != kAllFields) {
861	        std::string missing;
862	        auto add = [&](unsigned b, const char* name) {
863	            if (!(seen & b)) {
864	                if (!missing.empty()) {
865	                    missing += ", ";
866	                }
867	                missing += '"';
868	                missing += name;
869	                missing += '"';
870	            }
871	        };
872	        add(kVersion, "version");
873	        add(kRoot, "root");
874	        add(kLeafCount, "leaf_count");
875	        add(kLeafIndex, "leaf_index");
876	        add(kLeaf, "leaf");
877	        add(kSiblings, "siblings");
878	        p.fail("proof object is missing required field(s): " + missing);
879	    }
880	
881	    if (!p.error.empty()) {
882	        result.error = "proof text rejected: " + p.error;
883	        return result;
884	    }
