    {
        // 三文件位置 2 的形状只允许一个 left 兄弟；文本里就只给一个，
        // 读取端不得“补出”被提升层的记录。
        const Digest p = branchaudit::merkle_parent(la, labc);
        const Digest root3 = branchaudit::merkle_parent(p, lempty);
        const std::string j =
            proof_json(root3, 3, 2, lempty,
