        p.ws();
        if (p.eof() || p.peek() != '"') {
            return p.fail(std::string(spec.expect_key_msg));
        }
        std::string key;
        if (!p.read_string(key)) return false;
        p.ws();
        if (p.eof() || p.peek() != ':') {
            return p.fail("expected ':' after " + std::string(spec.key_noun) + " \"" + key + "\"");
        }
        ++p.pos;
        const JsonFieldSpec* field = nullptr;
        for (size_t i = 0; i < spec.field_count; ++i)
            if (spec.fields[i].name == key) { field = &spec.fields[i]; break; }
        if (!field) {
            return p.fail("undefined field \"" + key + "\" " + std::string(spec.undefined_suffix));
        }
        if (seen & field->bit) {
            return p.fail("duplicate field \"" + key + "\" " + std::string(spec.duplicate_suffix));
        }
        if (!field->read_value(p, target)) return false;
        seen |= field->bit;
        p.ws();
        if (p.eof()) return p.fail(std::string(spec.unterminated_msg));
        if (p.peek() == '}') { ++p.pos; return true; }
        if (p.peek() != ',') return p.fail(std::string(spec.separator_msg));
        ++p.pos;
    }
}
