        kVersion = 1u << 0,
        kRoot = 1u << 1,
        kLeafCount = 1u << 2,
        kLeafIndex = 1u << 3,
        kLeaf = 1u << 4,
        kSiblings = 1u << 5,
    };
    constexpr unsigned kAllFields = kVersion | kRoot | kLeafCount |
                                    kLeafIndex | kLeaf | kSiblings;
